// The statuses a review can have
type ReviewStatus string

const (
	ReviewStatusPending   ReviewStatus = "pending"
	ReviewStatusPublished ReviewStatus = "published"
	ReviewStatusRemoved   ReviewStatus = "removed"
)

func NewReviewStatusFromString(s string) (ReviewStatus, error) {
	switch s {
	case "pending":
		return ReviewStatusPending, nil
	case "published":
		return ReviewStatusPublished, nil
	case "removed":
		return ReviewStatusRemoved, nil
	}
	var t ReviewStatus
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

